package lab;

import java.util.List;
import javax.naming.InitialContext;
import jakarta.persistence.EntityManager;
import org.springframework.expression.spel.standard.SpelExpressionParser;
import org.springframework.web.bind.annotation.*;

@RestController
@RequestMapping("/api/orders")
public class OrderController {

    private OrderRepository orders;
    private EntityManager em;

    @GetMapping("/{id}")
    public Order show(@PathVariable Long id) {
        return orders.findById(id).orElseThrow();
    }

    @PostMapping
    public Order create(@RequestBody Order order) {
        return orders.save(order);
    }

    @GetMapping("/search")
    public List<?> search(@RequestParam String note) {
        return em.createQuery("select o from Order o where o.note like '%" + note + "%'").getResultList();
    }

    @GetMapping("/price")
    public Object price(@RequestParam String formula) {
        return new SpelExpressionParser().parseExpression(formula).getValue();
    }

    @GetMapping("/resource")
    public Object resource(@RequestParam String name) throws Exception {
        return new InitialContext().lookup(name);
    }
}

