package lab;

import java.util.List;
import jakarta.persistence.EntityManager;
import jakarta.validation.Valid;
import org.springframework.security.access.prepost.PreAuthorize;
import org.springframework.security.core.annotation.AuthenticationPrincipal;
import org.springframework.web.bind.annotation.*;

@RestController
@RequestMapping("/api/invoices")
public class InvoiceController {

    private InvoiceRepository invoices;
    private EntityManager em;

    @GetMapping("/{id}")
    public Invoice show(@PathVariable Long id, @AuthenticationPrincipal AppUser user) {
        return invoices.findByIdAndOwnerId(id, user.getId()).orElseThrow();
    }

    @PostMapping
    public Invoice create(@Valid @RequestBody CreateInvoiceRequest req, @AuthenticationPrincipal AppUser user) {
        Invoice i = new Invoice();
        i.setAmount(req.getAmount());
        i.setOwnerId(user.getId());
        return invoices.save(i);
    }

    @GetMapping("/search")
    @PreAuthorize("hasRole('ACCOUNTANT')")
    public List<?> search(@RequestParam String note) {
        return em.createQuery("select i from Invoice i where i.note like :n").setParameter("n", "%" + note + "%").getResultList();
    }
}
